{
    "testCases": [
        {
            "group": "verify_success_fullSignature",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with matching TSIG RR and correct MAC (fullSignature=true)" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "TSIGRecord containing same key name, algorithm, time, and MAC as generated by the request" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "0   // Rcode.NOERROR – verification succeeds",
                    "description": "A normal successful verification where the full MAC (including the request MAC) is present and matches the computed HMAC."
                }
            ]
        },
        {
            "group": "verify_success_truncatedSignature",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with matching TSIG RR but only the first 10 bytes of the MAC (fullSignature=false)" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "TSIGRecord with same key name, algorithm, time, and full MAC as the request" },
                        { "parameter": "fullSignature", "value": "false" }
                    ],
                    "expected": "0   // Rcode.NOERROR – verification succeeds even with a truncated MAC when fullSignature is false",
                    "description": "Verification succeeds when only a truncated MAC is supplied (as allowed for UDP responses) and the truncated portion matches the computed MAC."
                }
            ]
        },
        {
            "group": "verify_badSignature",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with TSIG RR whose MAC is deliberately altered" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "Valid TSIGRecord from the request" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "16   // Rcode.BADSIG – MAC does not match",
                    "description": "The method must detect a mismatching MAC and return BADSIG."
                }
            ]
        },
        {
            "group": "verify_timeOutsideFudge",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with TSIG RR whose time stamp is 10 minutes older than the current time" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "Valid TSIGRecord from the request" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "18   // Rcode.BADTIME – time stamp outside allowed fudge window",
                    "description": "When the TSIG time stamp is outside the ±FUDGE (5 minutes) window, verification must fail with BADTIME."
                }
            ]
        },
        {
            "group": "verify_nullRequestTSIG",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message without any TSIG RR" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "null" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "1   // Rcode.FORMERR – missing request TSIG record",
                    "description": "If the request TSIG record is null (e.g., the incoming message is not signed), verification should return FORMERR."
                }
            ]
        },
        {
            "group": "verify_algorithmMismatch",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with TSIG RR using HMAC‑SHA256" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "TSIGRecord from request that uses HMAC‑MD5" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "16   // Rcode.BADSIG – algorithm identifier differs",
                    "description": "Verification must fail when the algorithm name in the response does not match the algorithm of the request."
                }
            ]
        },
        {
            "group": "verify_keyNameMismatch",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with TSIG RR whose key name is \"example.com.\" but request uses \"other.com.\"" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "TSIGRecord with key name \"other.com.\"" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "16   // Rcode.BADSIG – different key name",
                    "description": "If the key name in the response differs from the request key name, verification must return BADSIG."
                }
            ]
        },
        {
            "group": "verify_macExceptionHandling",
            "cases": [
                {
                    "input": [
                        { "parameter": "m", "value": "Message with valid TSIG RR but the underlying Mac algorithm throws GeneralSecurityException (e.g., unsupported algorithm)" },
                        { "parameter": "messageBytes", "value": "byte[] of the original DNS wire format" },
                        { "parameter": "requestTSIG", "value": "Valid TSIGRecord from the request" },
                        { "parameter": "fullSignature", "value": "true" }
                    ],
                    "expected": "1   // Rcode.FORMERR – verification cannot proceed due to crypto error",
                    "description": "When the Mac instance cannot be created or initialized, the method should catch the exception and return FORMERR."
                }
            ]
        }
    ]
}
